const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const test = require("node:test");
const vm = require("node:vm");
const basemap = require("../src/main/resources/marketweb/tellus-basemap.js");

// Coordinates independently read from the saved world, rather than generated by the map projection.
const MARKET = { marketId: "saved-market", marketName: "Saved market", x: 28110, z: -48635 };
const CLAIMS = [
  { chunkX: 1756, chunkZ: -3040, nationId: "west", fillRgb: 0x123456, borderRgb: 0x654321 },
  { chunkX: 1761, chunkZ: -3038, nationId: "east", fillRgb: 0x123456, borderRgb: 0x654321 }
];

function near(actual, expected, message, tolerance = 1e-7) {
  assert.ok(Math.abs(actual - expected) <= tolerance, `${message}: expected ${expected}, got ${actual}`);
}

function recordingContext() {
  const calls = [];
  let offset = { x: 0, y: 0 };
  const stack = [];
  const context = { calls,
    save() { stack.push({ ...offset }); },
    restore() { offset = stack.pop(); },
    setTransform(_a, _b, _c, _d, x, y) { offset = { x, y }; },
    translate(x, y) { offset.x += x; offset.y += y; }
  };
  for (const name of ["clearRect", "fillRect", "strokeRect", "drawImage", "beginPath", "moveTo", "lineTo", "arc", "fill", "stroke", "fillText", "setLineDash"]) {
    context[name] = (...args) => calls.push({ name, args, offset: { ...offset } });
  }
  return context;
}

function mapHarness({ dpr = 1, width = 1000, height = 600, zoom = 0.85, leaflet = true, mobile = false } = {}) {
  const filename = path.join(__dirname, "../src/main/resources/marketweb/map.js");
  const source = fs.readFileSync(filename, "utf8");
  const observed = source.replace(/\}\)\(\);\s*$/, "window.__projectionTest = { state, resizeCanvas, worldToScreen, screenToWorld, syncSquaremapTerrain, updateCoordReadout, screenRectForWorldBounds, drawTerritories, drawMarkets, drawHoverHighlight, bindCanvasEvents, centerOn, zoomAt, ensureStaticLayer, renderOverlayFrame, staticAnchorDriftPx, visibleTileRange, drawPixelAlignedTile, drawRoute, nearestRouteNode, nearestShipment, hitTest, renderTooltip };})();");
  assert.notEqual(observed, source, "the observer attaches to the real map closure");
  const offscreens = [];
  const environment = {
    window: {
      devicePixelRatio: dpr, innerWidth: mobile ? 400 : 1400,
      matchMedia: () => ({ matches: false }),
      clearTimeout() {}, clearInterval() {}, SailboatTellusBasemap: basemap,
      L: { latLng: (lat, lng) => ({ lat, lng }) }
    },
    navigator: { maxTouchPoints: mobile ? 1 : 0 },
    document: { createElement(type) {
      assert.equal(type, "canvas");
      const context = recordingContext();
      const canvas = { width: 0, height: 0, context, getContext: () => context };
      offscreens.push(canvas);
      return canvas;
    } },
    performance,
    requestAnimationFrame: () => 1,
    cancelAnimationFrame() {}
  };
  vm.runInNewContext(observed, environment, { filename });
  const api = environment.window.__projectionTest;
  const { state } = api;
  const rect = { left: 31, top: 47, width, height };
  let rectReads = 0;
  const handlers = new Map();
  const context = recordingContext();
  const canvas = {
    width: 0, height: 0,
    getBoundingClientRect() { rectReads++; return rect; },
    addEventListener: (name, callback) => handlers.set(name, callback),
    setPointerCapture() {}, releasePointerCapture() {}
  };
  state.canvas = canvas;
  state.ctx = context;
  state.center = { x: MARKET.x, z: MARKET.z };
  state.zoom = zoom;
  state.world = { tellus: true, worldScale: 100 };
  state.markets = [MARKET];
  state.territories = CLAIMS;
  state.layers.shipments = false;
  let view;
  if (leaflet) {
    state.leafletMap = {
      invalidateSize() {}, remove() {},
      setView(center, mapZoom) { view = { center, zoom: mapZoom }; }
    };
  }
  api.resizeCanvas();
  api.bindCanvasEvents();
  return {
    ...api, context, canvas, rect, offscreens,
    // Leaflet CRS.Simple works in CSS pixels. This oracle is independent of both Canvas conversion functions.
    terrain(point) {
      assert.ok(view, "the actual Leaflet sync supplies the view");
      return { x: rect.width / 2 + (point.x - view.center.lng) * 2 ** view.zoom,
        y: rect.height / 2 + (point.z + view.center.lat) * 2 ** view.zoom };
    },
    css(point) { return { x: point.x * rect.width / canvas.width, y: point.y * rect.height / canvas.height }; },
    client(point) { return { x: rect.left + point.x, y: rect.top + point.y }; },
    dispatch(name, event = {}) { handlers.get(name)({ pointerId: 1, preventDefault() {}, ...event }); },
    setViewport(next) { Object.assign(rect, next); },
    setDpr(next) { environment.window.devicePixelRatio = next; },
    rectReads: () => rectReads,
    unmount: environment.window.SailboatMarketMap.unmount
  };
}

test("saved claims and market share Leaflet CSS coordinates across device ratios and zoom levels", () => {
  const points = [MARKET, ...CLAIMS.flatMap((claim) => {
    const x = claim.chunkX * 16, z = claim.chunkZ * 16;
    return [{ x, z }, { x: x + 16, z }, { x, z: z + 16 }, { x: x + 16, z: z + 16 }, { x: x + 8, z: z + 8 }];
  })];
  for (const dpr of [1, 1.25, 1.5, 2, 3]) {
    for (const zoom of [1 / 2048, 0.25, 0.85, 2, 8]) {
      const map = mapHarness({ dpr, zoom, width: 1508, height: 820 });
      assert.equal(map.canvas.width, Math.floor(1508 * Math.min(dpr, 2)), "desktop DPR is capped at two");
      for (const center of [MARKET, { x: MARKET.x - 100, z: MARKET.z + 70 }]) {
        map.state.center = { x: center.x, z: center.z };
        map.syncSquaremapTerrain();
        for (const point of points) {
          const actual = map.css(map.worldToScreen(point));
          const expected = map.terrain(point);
          near(actual.x, expected.x, `DPR ${dpr}, zoom ${zoom}, world X ${point.x}`);
          near(actual.y, expected.y, `DPR ${dpr}, zoom ${zoom}, world Z ${point.z}`);
        }
      }
    }
  }
});

test("Canvas projection uses actual per-axis backing ratios after floors and minimum sizes", () => {
  for (const viewport of [{ dpr: 1.25, width: 777.7, height: 555.3 }, { dpr: 1, width: 280, height: 180 }, { dpr: 3, width: 319.3, height: 260.7, mobile: true }]) {
    const map = mapHarness(viewport);
    for (const point of [{ x: MARKET.x + 80, z: MARKET.z - 32 }, { x: MARKET.x - 80, z: MARKET.z + 32 }]) {
      const expected = map.terrain(point);
      const actual = map.css(map.worldToScreen(point));
      near(actual.x, expected.x, "nonuniform backing X");
      near(actual.y, expected.y, "nonuniform backing Y");
      const world = map.screenToWorld(expected.x * map.canvas.width / map.rect.width, expected.y * map.canvas.height / map.rect.height);
      near(world.x, point.x, "inverse projection X against terrain");
      near(world.z, point.z, "inverse projection Z against terrain");
    }
    const reads = map.rectReads();
    for (let i = 0; i < 50; i++) map.worldToScreen({ x: i, z: -i });
    assert.equal(map.rectReads(), reads, "vertices do not trigger layout reads");
  }
});

test("rendered territory edges, market anchor, routes, and hover bounds use the same CSS projection", () => {
  const map = mapHarness({ dpr: 1.5, width: 1508, height: 820 });
  map.state.center = { x: MARKET.x - 25, z: MARKET.z + 10 };
  map.syncSquaremapTerrain();
  map.drawTerritories(map.context);
  const fills = map.context.calls.filter((call) => call.name === "fillRect");
  assert.equal(fills.length, 2);
  for (let i = 0; i < CLAIMS.length; i++) {
    const claim = CLAIMS[i];
    const start = map.terrain({ x: claim.chunkX * 16, z: claim.chunkZ * 16 });
    const end = map.terrain({ x: claim.chunkX * 16 + 16, z: claim.chunkZ * 16 + 16 });
    const [x, y, width, height] = fills[i].args;
    const actualStart = map.css({ x, y });
    const actualEnd = map.css({ x: x + width, y: y + height });
    const tolerance = 1 / 1.5;
    near(actualStart.x, start.x, "drawn claim left", tolerance);
    near(actualStart.y, start.y, "drawn claim top", tolerance);
    near(actualEnd.x, end.x, "drawn claim right", tolerance);
    near(actualEnd.y, end.y, "drawn claim bottom", tolerance);
  }
  map.drawMarkets(map.context);
  const anchor = map.context.calls.find((call) => call.name === "arc");
  const marketCss = map.css(anchor.offset);
  near(marketCss.x, map.terrain(MARKET).x, "drawn market X");
  near(marketCss.y, map.terrain(MARKET).y, "drawn market Y");
  map.context.calls.length = 0;
  const claim = CLAIMS[1];
  map.state.hover = { type: "territory", data: claim };
  map.drawHoverHighlight(map.context);
  const hover = map.context.calls.find((call) => call.name === "strokeRect");
  near(hover.args[2] * map.rect.width / map.canvas.width, 16 * map.state.zoom, "hover width CSS");
  near(hover.args[3] * map.rect.height / map.canvas.height, 16 * map.state.zoom, "hover height CSS");
  map.drawRoute(map.context, [{ x: MARKET.x + 74, z: MARKET.z + 35 }, MARKET], false, "white", 2);
  const route = map.context.calls.filter((call) => call.name === "moveTo" || call.name === "lineTo");
  near(map.css({ x: route[0].args[0], y: route[0].args[1] }).x, map.terrain({ x: MARKET.x + 74, z: MARKET.z + 35 }).x, "route X");
});

test("nonuniform backing scales keep the territory hover rectangle the same CSS size as its chunk", () => {
  const map = mapHarness({ dpr: 1, width: 280, height: 180 });
  map.state.hover = { type: "territory", data: CLAIMS[1] };
  map.drawHoverHighlight(map.context);
  const hover = map.context.calls.find((call) => call.name === "strokeRect");
  const actual = map.css({ x: hover.args[0], y: hover.args[1] });
  const expected = map.terrain({ x: 28176, z: -48608 });
  near(actual.x, expected.x, "nonuniform hover X");
  near(actual.y, expected.y, "nonuniform hover Y");
  near(hover.args[2] * map.rect.width / map.canvas.width, 16 * map.state.zoom, "nonuniform hover CSS width");
  near(hover.args[3] * map.rect.height / map.canvas.height, 16 * map.state.zoom, "nonuniform hover CSS height");
});

test("coordinate readout and hit testing identify the world under Leaflet rather than sharing a faulty round trip", () => {
  const map = mapHarness({ dpr: 2 });
  const readout = {};
  map.state.toolbar = { querySelector: () => readout };
  const point = { x: 28184, z: -48600 };
  const client = map.client(map.terrain(point));
  map.updateCoordReadout(client.x, client.y);
  assert.match(readout.innerHTML, /X: 28184\s+.*Z: -48600/);
  map.state.layers.markets = false;
  const territory = map.hitTest(client.x, client.y);
  assert.equal(territory?.type, "territory");
  assert.equal(territory?.data.nationId, "east");
  map.state.layers.markets = true;
  map.state.markets = [{ ...MARKET, ...point }];
  assert.equal(map.hitTest(client.x, client.y)?.type, "market");
  const screen = map.worldToScreen(point);
  const world = map.screenToWorld(screen.x, screen.y);
  near(world.x, point.x, "roundtrip X");
  near(world.z, point.z, "roundtrip Z");
});

test("dragging moves the Leaflet view by the pointer distance on every backing ratio", () => {
  for (const options of [{ dpr: 2 }, { dpr: 1.25, width: 777.7, height: 555.3 }, { dpr: 1, width: 280, height: 180 }]) {
    const map = mapHarness(options);
    const before = { ...map.state.center };
    map.dispatch("pointerdown", { clientX: 100, clientY: 150 });
    map.dispatch("pointermove", { clientX: 173, clientY: 109 });
    near(map.state.center.x, before.x - 73 / map.state.zoom, "dragged center X");
    near(map.state.center.z, before.z + 41 / map.state.zoom, "dragged center Z");
    map.syncSquaremapTerrain();
    const actual = map.css(map.worldToScreen(MARKET));
    const expected = map.terrain(MARKET);
    near(actual.x, expected.x, "drag overlay X");
    near(actual.y, expected.y, "drag overlay Y");
  }
});

test("wheel zoom keeps the terrain coordinate under the CSS cursor anchored", () => {
  const map = mapHarness({ dpr: 1.5 });
  const point = { x: 28184, z: -48600 };
  const before = map.terrain(point);
  const client = map.client(before);
  map.dispatch("wheel", { clientX: client.x, clientY: client.y, deltaY: -1 });
  map.syncSquaremapTerrain();
  const after = map.terrain(point);
  near(after.x, before.x, "Leaflet cursor anchor X");
  near(after.y, before.y, "Leaflet cursor anchor Y");
  near(map.css(map.worldToScreen(point)).x, before.x, "Canvas cursor anchor X");
  near(map.css(map.worldToScreen(point)).y, before.y, "Canvas cursor anchor Y");
});

test("shipment and route-node hit distances use backing pixels consistently with their drawn paths", () => {
  const map = mapHarness({ dpr: 2 });
  const shipment = { shippingOrderId: "route", points: [
    { x: MARKET.x, z: MARKET.z - 20, origin: 0 },
    { x: MARKET.x, z: MARKET.z + 20, origin: 0 }
  ] };
  map.state.shipments = [shipment];
  assert.equal(map.nearestShipment({ x: MARKET.x + 5, z: MARKET.z }, 9), shipment, "8.5 backing pixels hits the trail");
  assert.equal(map.nearestShipment({ x: MARKET.x + 6, z: MARKET.z }, 9), null, "10.2 backing pixels misses the trail");
  const node = map.terrain(shipment.points[0]);
  assert.equal(map.nearestRouteNode(node.x * 2 + 7, node.y * 2, 8)?.origin, 0);
  assert.equal(map.nearestRouteNode(node.x * 2 + 9, node.y * 2, 8), null);
});

test("cached static overlays translate with Leaflet without rebuilding inside the padding", () => {
  const map = mapHarness({ dpr: 1.5 });
  map.renderOverlayFrame();
  const canvas = map.state.staticCanvas;
  const builtCalls = canvas.context.calls.length;
  const first = map.context.calls.filter((call) => call.name === "drawImage").at(-1);
  map.state.center.x += 20;
  map.state.center.z -= 12;
  map.renderOverlayFrame();
  assert.equal(map.state.staticCanvas, canvas);
  assert.equal(canvas.context.calls.length, builtCalls, "dragging within padding reuses rendered claims");
  const last = map.context.calls.filter((call) => call.name === "drawImage").at(-1);
  near(last.args[1] - first.args[1], -20 * map.state.zoom * map.canvas.width / map.rect.width, "cache translation X", 0.5);
  near(last.args[2] - first.args[2], 12 * map.state.zoom * map.canvas.height / map.rect.height, "cache translation Y", 0.5);
  near(map.staticAnchorDriftPx(), 20 * map.state.zoom * map.canvas.width / map.rect.width, "cache drift uses backing pixels");
});

test("padded caches retain offscreen claims and market pins as dragging brings them into view", () => {
  const map = mapHarness({ dpr: 1.5, zoom: 1, width: 400, height: 300 });
  const marker = { ...MARKET, x: 28392, z: -48632 };
  const claim = { ...CLAIMS[1], chunkX: 1774, chunkZ: -3040 };
  map.state.markets = [marker];
  map.state.territories = [claim];
  const initial = map.terrain(marker);
  assert.ok(initial.x > map.rect.width + 32, "the fixture starts beyond the old viewport cull margin");
  map.renderOverlayFrame();
  const cache = map.state.staticCanvas;
  const markerDraw = cache.context.calls.find((call) => call.name === "arc");
  assert.ok(markerDraw, "the buffer includes the currently offscreen pin");
  const claimDraw = cache.context.calls.find((call) => call.name === "fillRect");
  assert.ok(claimDraw && claimDraw.args[0] !== 10, "the buffer includes the currently offscreen claim");
  assert.ok(cache.context.calls.some((call) => call.name === "lineTo"), "claim borders are also cached");
  const buildCount = cache.context.calls.length;
  map.dispatch("pointerdown", { clientX: 250, clientY: 150 });
  map.dispatch("pointermove", { clientX: 90, clientY: 150 });
  map.syncSquaremapTerrain();
  map.renderOverlayFrame();
  assert.equal(cache.context.calls.length, buildCount, "a drag within the buffer reuses the cache");
  const blit = map.context.calls.filter((call) => call.name === "drawImage").at(-1);
  const markerCss = map.css({ x: markerDraw.offset.x + blit.args[1], y: markerDraw.offset.y + blit.args[2] });
  const expectedMarker = map.terrain(marker);
  assert.ok(expectedMarker.x > 0 && expectedMarker.x < map.rect.width, "the drag brings the fixture into view");
  near(markerCss.x, expectedMarker.x, "cached market X after drag", 0.5 / 1.5);
  near(markerCss.y, expectedMarker.y, "cached market Y after drag", 0.5 / 1.5);
  const claimCss = map.css({ x: claimDraw.args[0] + claimDraw.offset.x + blit.args[1],
    y: claimDraw.args[1] + claimDraw.offset.y + blit.args[2] });
  const expectedClaim = map.terrain({ x: claim.chunkX * 16, z: claim.chunkZ * 16 });
  near(claimCss.x, expectedClaim.x, "cached claim X after drag", 1.5 / 1.5);
  near(claimCss.y, expectedClaim.y, "cached claim Y after drag", 1.5 / 1.5);
  map.zoomAt(map.canvas.width / 2, map.canvas.height / 2, 1.25);
  map.syncSquaremapTerrain();
  map.renderOverlayFrame();
  assert.ok(cache.context.calls.length > buildCount, "zoom rebuilds cached world geometry");
  const zoomedDraw = cache.context.calls.filter((call) => call.name === "arc").at(-1);
  const zoomedBlit = map.context.calls.filter((call) => call.name === "drawImage").at(-1);
  const zoomedCss = map.css({ x: zoomedDraw.offset.x + zoomedBlit.args[1], y: zoomedDraw.offset.y + zoomedBlit.args[2] });
  near(zoomedCss.x, map.terrain(marker).x, "cached pin X after zoom");
  near(zoomedCss.y, map.terrain(marker).y, "cached pin Y after zoom");
  const zoomedClaim = cache.context.calls.filter((call) => call.name === "fillRect" && call.args[0] !== 10).at(-1);
  const zoomedClaimCss = map.css({ x: zoomedClaim.args[0] + zoomedClaim.offset.x + zoomedBlit.args[1],
    y: zoomedClaim.args[1] + zoomedClaim.offset.y + zoomedBlit.args[2] });
  const zoomedClaimExpected = map.terrain({ x: claim.chunkX * 16, z: claim.chunkZ * 16 });
  near(zoomedClaimCss.x, zoomedClaimExpected.x, "cached claim X after zoom", 1 / 1.5);
  near(zoomedClaimCss.y, zoomedClaimExpected.y, "cached claim Y after zoom", 1 / 1.5);
});

test("camera interactions immediately clear the real pointer tooltip while preserving selected world pins", () => {
  const actions = [
    (map) => map.zoomAt(map.canvas.width / 2, map.canvas.height / 2, 1.25),
    (map) => map.centerOn({ x: MARKET.x + 100, z: MARKET.z - 10 }, 1),
    (map) => map.dispatch("pointerdown", { clientX: 120, clientY: 140 }),
    (map) => map.dispatch("wheel", { clientX: 120, clientY: 140, deltaY: -1 })
  ];
  for (const action of actions) {
    const map = mapHarness({ dpr: 1.5 });
    map.state.root = { getBoundingClientRect: () => map.rect };
    map.state.tooltip = { hidden: true, innerHTML: "", style: {}, querySelectorAll: () => [] };
    const selected = { type: "market", data: MARKET };
    const hover = { type: "territory", data: CLAIMS[1] };
    map.state.selected = selected;
    map.state.hover = hover;
    map.renderTooltip(hover, 120, 140);
    assert.equal(map.state.tooltip.hidden, false, "the actual tooltip renderer first shows the tip");
    assert.ok(map.state.tooltip.innerHTML.length > 0);
    map.state.animationFrame = 0;
    action(map);
    assert.equal(map.state.hover, null, "a stale pointer hover cannot highlight the wrong position");
    assert.equal(map.state.tooltip.hidden, true, "the DOM tooltip hides synchronously with the interaction");
    assert.equal(map.state.tooltip.innerHTML, "");
    assert.equal(map.state.selected, selected, "selection remains attached to its world object");
    assert.notEqual(map.state.animationFrame, 0, "the cleared Canvas hover highlight is repainted");
  }
});

test("drag coordinate readout uses the updated center on the same pointer event", () => {
  const map = mapHarness({ dpr: 1.5 });
  const readout = {};
  map.state.toolbar = { querySelector: () => readout };
  map.dispatch("pointerdown", { clientX: 350, clientY: 210 });
  map.dispatch("pointermove", { clientX: 423, clientY: 169 });
  const expectedX = Math.round(map.state.center.x + (423 - map.rect.left - map.rect.width / 2) / map.state.zoom);
  const expectedZ = Math.round(map.state.center.z + (169 - map.rect.top - map.rect.height / 2) / map.state.zoom);
  assert.equal(readout.innerHTML, `X: ${expectedX} \u00a0 Z: ${expectedZ}`);
});

test("resize updates ratios and invalidates static geometry even when minimum backing dimensions are unchanged", () => {
  const map = mapHarness({ dpr: 1, width: 280, height: 180 });
  map.renderOverlayFrame();
  const canvas = map.state.staticCanvas;
  const calls = canvas.context.calls.length;
  map.setViewport({ width: 300, height: 200 });
  map.resizeCanvas();
  map.renderOverlayFrame();
  assert.ok(canvas.context.calls.length > calls, "changed CSS dimensions rebuild cached coordinates");
  const point = { x: MARKET.x + 74, z: MARKET.z + 35 };
  near(map.css(map.worldToScreen(point)).x, map.terrain(point).x, "resize projection X");
  near(map.css(map.worldToScreen(point)).y, map.terrain(point).y, "resize projection Y");
  map.setDpr(2);
  map.setViewport({ width: 900.5, height: 610.25 });
  map.resizeCanvas();
  near(map.css(map.worldToScreen(point)).x, map.terrain(point).x, "new display DPR X");
  near(map.css(map.worldToScreen(point)).y, map.terrain(point).y, "new display DPR Y");
  map.unmount();
  assert.equal(map.state.canvasScaleX, 1, "teardown resets X for the next map");
  assert.equal(map.state.canvasScaleY, 1, "teardown resets Y for the next map");
});

test("fallback terrain tiles and Canvas claims remain aligned without Leaflet", () => {
  const map = mapHarness({ dpr: 2, leaflet: false });
  const x = 28176, z = -48608;
  map.drawPixelAlignedTile(map.context, {}, x, z, 16);
  const image = map.context.calls.find((call) => call.name === "drawImage");
  const rect = map.screenRectForWorldBounds(x, z, 16, 16);
  near(image.args[1] + 1, rect.x, "fallback tile left agrees with claim");
  near(image.args[2] + 1, rect.y, "fallback tile top agrees with claim");
  const css = map.css({ x: rect.x, y: rect.y });
  near(css.x, map.rect.width / 2 + (x - MARKET.x) * map.state.zoom, "fallback X CSS", 0.5);
  near(css.y, map.rect.height / 2 + (z - MARKET.z) * map.state.zoom, "fallback Z CSS", 0.5);
  map.state.layers.terrain = false;
  map.renderOverlayFrame();
  assert.ok(map.state.staticCanvas.context.calls.some((call) => call.name === "fillRect"));
});

test("fallback tile enumeration covers the CSS viewport independently of backing resolution", () => {
  for (const dpr of [1, 1.25, 2]) {
    const map = mapHarness({ dpr, leaflet: false });
    const actual = map.visibleTileRange(0);
    assert.equal(actual.minX, Math.floor((MARKET.x - map.rect.width / (2 * map.state.zoom)) / 512) - 1);
    assert.equal(actual.maxX, Math.floor((MARKET.x + map.rect.width / (2 * map.state.zoom)) / 512) + 1);
    assert.equal(actual.minZ, Math.floor((MARKET.z - map.rect.height / (2 * map.state.zoom)) / 512) - 1);
    assert.equal(actual.maxZ, Math.floor((MARKET.z + map.rect.height / (2 * map.state.zoom)) / 512) + 1);
  }
});
